using System;using System.IO;using System.Linq;using System.Data;using System.Data.SqlClient;using System.Collections.Generic;
namespace MuEditorPhoenix {
 public partial class ItemBuffer {
  public byte[] Data,Original;public int Count{get{return Data.Length/25;}}public bool Dirty{get{return !Data.SequenceEqual(Original);}}
  public ItemBuffer(byte[] data){if(data==null||data.Length%25!=0)throw new Exception("Registro de itens incompatível.");Data=(byte[])data.Clone();Original=(byte[])data.Clone();}
  public byte[] Get(int slot){if(slot<0||slot>=Count)throw new Exception("Slot inválido.");return Data.Skip(slot*25).Take(25).ToArray();}
  public bool Empty(int slot){return Get(slot).All(b=>b==255);}
  public void Set(int slot,byte[] bytes){Get(slot);if(bytes.Length!=25)throw new Exception("Item deve ter 25 bytes.");Buffer.BlockCopy(bytes,0,Data,slot*25,25);}
  public int Id(int slot){var b=Get(slot);return b[0]+((b[7]&128)<<1)+((b[9]&240)<<5)+((b[9]&1)<<13);}
  public static List<int> Cells(int slot,ItemDef d,int start,int end){int x=(slot-start)%8,y=(slot-start)/8;if(slot<start||slot>=end||d.Width>8||x+d.Width>8||slot+(d.Height-1)*8+d.Width>end)throw new Exception("Item atravessa o limite da grade.");var cells=new List<int>();for(int dy=0;dy<d.Height;dy++)for(int dx=0;dx<d.Width;dx++)cells.Add(slot+dy*8+dx);return cells;}
  public static void Move(ItemBuffer source,int from,ItemBuffer target,int to,Catalog catalog,int targetStart,int targetEnd){if(source==target&&from==to)return;if(source.Empty(from)||!target.Empty(to))throw new Exception("Selecione um item e um destino vazio.");ItemDef def;if(!catalog.Items.TryGetValue(source.Id(from),out def))throw new Exception("Item desconhecido no Item.xml.");var occupied=new HashSet<int>();for(int slot=targetStart;slot<targetEnd;slot++){if((source==target&&slot==from)||target.Empty(slot))continue;ItemDef item;if(!catalog.Items.TryGetValue(target.Id(slot),out item))throw new Exception("Há item não identificado na grade de destino.");foreach(int cell in Cells(slot,item,targetStart,targetEnd))occupied.Add(cell);}foreach(int cell in Cells(to,def,targetStart,targetEnd))if(occupied.Contains(cell))throw new Exception("O item sobrepõe outro item.");if(target.NewItems.ContainsKey(to))throw new Exception("Há uma premiação pendente no destino.");NewItemMarker marker;bool isNew=source.NewItems.TryGetValue(from,out marker);target.Set(to,source.Get(from));source.Set(from,Enumerable.Repeat((byte)255,25).ToArray());if(isNew){source.NewItems.Remove(from);target.NewItems.Add(to,marker);}}
  public void Options(int slot,int level,int durability,bool skill,bool luck,int option,int excellent){if(Empty(slot))throw new Exception("Slot vazio.");var adapter=new InventoryBlob();byte[] raw=Enumerable.Repeat((byte)255,5975).ToArray();Buffer.BlockCopy(Get(slot),0,raw,0,25);adapter.Load(raw);adapter.Options(0,level,durability,skill,luck,option,excellent);Set(slot,adapter.Slot(0));}
 }
 public partial class Database {
  public DataTable OriginalWarehouse,MasterOriginal,MasterDraft;public ItemBuffer Warehouse;public int WarehousePage=-1;public bool CrossStorageDirty=false;
  public bool Connected{get{return !string.IsNullOrEmpty(ConnectionString);}}
  public DataTable BrowseCharacters(string term){return Query("SELECT TOP(1000) c.AccountID,c.Name,c.cLevel,c.Class,c.ResetCount,ISNULL(s.ConnectStat,0) AS Online FROM dbo.Character c LEFT JOIN dbo.MEMB_STAT s ON s.memb___id=c.AccountID WHERE c.Name LIKE @q OR c.AccountID LIKE @q ORDER BY c.Name",new SqlParameter("@q",SqlDbType.VarChar,110){Value="%"+term+"%"});}
  public DataTable BrowseAccounts(string term){return Query("SELECT TOP(1000) m.memb___id AS Account,m.AccountLevel,m.AccountExpireDate,m.bloc_code,ISNULL(s.ConnectStat,0) AS Online FROM dbo.MEMB_INFO m LEFT JOIN dbo.MEMB_STAT s ON s.memb___id=m.memb___id WHERE m.memb___id LIKE @q ORDER BY m.memb___id",new SqlParameter("@q",SqlDbType.VarChar,110){Value="%"+term+"%"});}
  public bool HasColumn(string table,string column){return Query("SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA='dbo' AND TABLE_NAME=@t AND COLUMN_NAME=@c",new SqlParameter("@t",table),new SqlParameter("@c",column)).Rows.Count!=0;}
  public DataTable LoadDetailedCharacter(string name){var main=LoadCharacter(name);var optional=new[]{"Class","MapNumber","MapPosX","MapPosY","PkCount","PkLevel","RuudMoney","ExtInventory"}.Where(col=>HasColumn("Character",col)).ToArray();if(optional.Length>0){var details=Query("SELECT "+string.Join(",",optional.Select(col=>"["+col+"]"))+" FROM dbo.Character WHERE Name=@n AND AccountID=@a",P("@n",name),P("@a",Account));foreach(var col in optional){OriginalCharacter.Columns.Add(col,details.Columns[col].DataType);OriginalCharacter.Rows[0][col]=details.Rows[0][col];main.Columns.Add(col,details.Columns[col].DataType);main.Rows[0][col]=details.Rows[0][col];}}
   MasterOriginal=null;MasterDraft=null;if(HasColumn("MasterSkillTree","MasterLevel")&&HasColumn("MasterSkillTree","MasterPoint")){MasterOriginal=Query("SELECT Name,MasterLevel,MasterPoint FROM dbo.MasterSkillTree WHERE Name=@n",P("@n",name));if(MasterOriginal.Rows.Count==1)MasterDraft=MasterOriginal.Copy();}return main;}
  public DataTable WarehousePages(){var table=new DataTable();table.Columns.Add("Number",typeof(int));table.Columns.Add("Name");if(HasColumn("warehouse","Items")&&Query("SELECT 1 FROM dbo.warehouse WHERE AccountID=@a",P("@a",Account)).Rows.Count>0)table.Rows.Add(-1,"Baú principal");if(HasColumn("ExtWarehouse","Number")){foreach(DataRow r in Query("SELECT Number FROM dbo.ExtWarehouse WHERE AccountID=@a ORDER BY Number",P("@a",Account)).Rows)table.Rows.Add(Convert.ToInt32(r[0]),"Ext "+r[0]);}return table;}
  public void LoadWarehouse(int page){if(CrossStorageDirty)throw new Exception("Salve ou descarte a transferência antes de trocar de baú.");string sql=page<0?"SELECT AccountID,Items,Money FROM dbo.warehouse WHERE AccountID=@a":"SELECT AccountID,Items,Money,Number FROM dbo.ExtWarehouse WHERE AccountID=@a AND Number=@page";OriginalWarehouse=page<0?Query(sql,P("@a",Account)):Query(sql,P("@a",Account),new SqlParameter("@page",page));if(OriginalWarehouse.Rows.Count!=1)throw new Exception("Baú não encontrado.");byte[] data=(byte[])OriginalWarehouse.Rows[0]["Items"];if(data.Length!=6000)throw new Exception("Baú fora do perfil MuDevs de 240 slots × 25 bytes.");Warehouse=new ItemBuffer(data);WarehousePage=page;}
  string WarehouseSelect(){return WarehousePage<0?"SELECT AccountID,Items,Money FROM dbo.warehouse WITH(UPDLOCK,HOLDLOCK) WHERE AccountID=@a":"SELECT AccountID,Items,Money,Number FROM dbo.ExtWarehouse WITH(UPDLOCK,HOLDLOCK) WHERE AccountID=@a AND Number=@page";}
  SqlParameter[] WarehouseParameters(){return WarehousePage<0?new[]{P("@a",Account)}:new[]{P("@a",Account),new SqlParameter("@page",WarehousePage)};}
  void UpdateWarehouse(SqlConnection c,SqlTransaction tx,int money,byte[] savedItems=null){if(Warehouse==null||Warehouse.Data.Length!=6000||money<0)throw new Exception("Baú inválido.");CurrentMatches(c,tx,WarehouseSelect(),OriginalWarehouse,WarehouseParameters());using(var cmd=new SqlCommand("UPDATE dbo."+(WarehousePage<0?"warehouse":"ExtWarehouse")+" SET Items=@items,Money=@money WHERE AccountID=@a"+(WarehousePage<0?"":" AND Number=@page")+" AND Items=@old",c,tx)){cmd.Parameters.AddRange(WarehouseParameters());cmd.Parameters.Add("@items",SqlDbType.VarBinary,6000).Value=savedItems??Warehouse.Data;cmd.Parameters.Add("@old",SqlDbType.VarBinary,6000).Value=Warehouse.Original;cmd.Parameters.Add("@money",SqlDbType.Int).Value=money;if(cmd.ExecuteNonQuery()!=1)throw new Exception("Conflito de baú.");}}
  public void SaveWarehouse(int money){if(CrossStorageDirty)throw new Exception("Transferência pendente: salve inventário e baú juntos.");var receipts=new List<CreatedItemReceipt>();LastCreatedItems.Clear();using(var c=Open())using(var tx=c.BeginTransaction(IsolationLevel.Serializable)){Offline(c,tx);CurrentMatches(c,tx,WarehouseSelect(),OriginalWarehouse,WarehouseParameters());var saved=MaterializeRewards(c,tx,Warehouse.Data,Warehouse.NewItems,"warehouse:"+WarehousePage,receipts);Guard.Backup("warehouse",new{account=Account,page=WarehousePage,before=OriginalWarehouse.Rows[0].ItemArray,after=Guard.Hex(saved),money=money,createdItems=receipts});UpdateWarehouse(c,tx,money,saved);tx.Commit();}LastCreatedItems=receipts;LoadWarehouse(WarehousePage);}
  public void SaveWorkspace(DataTable edited,int money){if(edited==null){SaveWarehouse(money);return;}CommitCharacter(edited,Warehouse!=null,money);}
  public void CommitCharacter(DataTable edited,bool withWarehouse,int money){var receipts=new List<CreatedItemReceipt>();LastCreatedItems.Clear();if(CrossStorageDirty&&!withWarehouse)throw new Exception("Transferência pendente: salve inventário e baú juntos.");if(OriginalCharacter==null||edited.Rows.Count!=1)throw new Exception("Carregue um personagem.");var row=edited.Rows[0];var allowed=new HashSet<string>(new[]{"Name","cLevel","Strength","Dexterity","Vitality","Energy","Leadership","LevelUpPoint","Money","ResetCount","MasterResetCount","CtlCode","Class","MapNumber","MapPosX","MapPosY","PkCount","PkLevel","RuudMoney","ExtInventory"});foreach(DataColumn col in edited.Columns){if(!allowed.Contains(col.ColumnName))throw new Exception("Coluna não permitida.");if(col.ColumnName=="Name")continue;long value=Convert.ToInt64(row[col]);if(value<0||value>int.MaxValue||(new[]{"Class","CtlCode","MapPosX","MapPosY"}.Contains(col.ColumnName)&&value>255)||(col.ColumnName=="cLevel"&&(value<1||value>400))||(col.ColumnName=="ExtInventory"&&value>2))throw new Exception("Valor inválido em "+col.ColumnName);}
   using(var c=Open())using(var tx=c.BeginTransaction(IsolationLevel.Serializable)){Offline(c,tx);CurrentMatches(c,tx,"SELECT * FROM dbo.Character WITH(UPDLOCK,HOLDLOCK) WHERE Name=@n AND AccountID=@a",OriginalCharacter,P("@n",Character),P("@a",Account));if(MasterDraft!=null){CurrentMatches(c,tx,"SELECT Name,MasterLevel,MasterPoint FROM dbo.MasterSkillTree WITH(UPDLOCK,HOLDLOCK) WHERE Name=@n",MasterOriginal,P("@n",Character));int level=Convert.ToInt32(MasterDraft.Rows[0]["MasterLevel"]),points=Convert.ToInt32(MasterDraft.Rows[0]["MasterPoint"]);if(level<0||level>65535||points<0)throw new Exception("Valores Master inválidos.");using(var cmd=new SqlCommand("UPDATE dbo.MasterSkillTree SET MasterLevel=@l,MasterPoint=@p WHERE Name=@n",c,tx)){cmd.Parameters.Add(P("@n",Character));cmd.Parameters.Add("@l",SqlDbType.Int).Value=level;cmd.Parameters.Add("@p",SqlDbType.Int).Value=points;if(cmd.ExecuteNonQuery()!=1)throw new Exception("Conflito Master.");}}
    if(withWarehouse)CurrentMatches(c,tx,WarehouseSelect(),OriginalWarehouse,WarehouseParameters());var savedInventory=MaterializeRewards(c,tx,Inventory.Data,InventoryNewItems,"inventory:"+Character,receipts);var savedWarehouse=withWarehouse?MaterializeRewards(c,tx,Warehouse.Data,Warehouse.NewItems,"warehouse:"+WarehousePage,receipts):null;
    Guard.Backup("workspace",new{createdItems=receipts,account=Account,character=Character,before=OriginalCharacter.Rows[0].ItemArray,after=row.ItemArray,inventoryAfter=Guard.Hex(savedInventory),warehouseBefore=withWarehouse?OriginalWarehouse.Rows[0].ItemArray:null,warehouseAfter=withWarehouse?Guard.Hex(savedWarehouse):null,masterBefore=MasterOriginal==null||MasterOriginal.Rows.Count==0?null:MasterOriginal.Rows[0].ItemArray});
    var fields=edited.Columns.Cast<DataColumn>().Where(col=>col.ColumnName!="Name").Select(col=>col.ColumnName).ToArray();using(var cmd=new SqlCommand("UPDATE dbo.Character SET "+string.Join(",",fields.Select((field,i)=>"["+field+"]=@p"+i))+",Inventory=@inventory WHERE Name=@n AND AccountID=@a AND Inventory=@old",c,tx)){cmd.Parameters.Add(P("@n",Character));cmd.Parameters.Add(P("@a",Account));for(int i=0;i<fields.Length;i++)cmd.Parameters.Add("@p"+i,SqlDbType.Int).Value=row[fields[i]];cmd.Parameters.Add("@inventory",SqlDbType.VarBinary,5975).Value=savedInventory;cmd.Parameters.Add("@old",SqlDbType.VarBinary,5975).Value=Inventory.Original;if(cmd.ExecuteNonQuery()!=1)throw new Exception("Conflito de inventário.");}if(withWarehouse)UpdateWarehouse(c,tx,money,savedWarehouse);tx.Commit();}
   LastCreatedItems=receipts;CrossStorageDirty=false;LoadDetailedCharacter(Character);if(withWarehouse)LoadWarehouse(WarehousePage);
  }
 }
}
